List<String> items = Arrays.asList("apple", "banana", "apricot", "cherry");

// groupingBy: Multi-bucket classification
Map<Character, List<String>> byFirstLetter = items.stream()
    .collect(Collectors.groupingBy(s -> s.charAt(0)));

// partitioningBy: Binary classification
Map<Boolean, List<String>> startsWithA = items.stream()
    .collect(Collectors.partitioningBy(s -> s.startsWith("a")));
